head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > E > onclick]<br/>트리 아이템 영역을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [        
        "트리 아이템 영역을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
        "value 파라미터로 클릭된 트리 아이템의 Value 값을 갖습니다.",
        "index 파라미터로 클릭된 트리 아이템의 인덱스값을 갖습니다.",
        "트리 아이템 영역은 토글 버튼, 아이콘, CheckBox, 라벨로 구분되며 전체 영역에서 onclick 이벤트가 발생합니다.  ",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        defaultImage : "/img/png.png",    
        expandedImage : "../../img/jpg.jpg",
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    // comp 생성 함수 호출    
    $c.gcm.createBasicTreeView(cList, eList); 
}



scwin.target1_onclick = function (value, index) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("value : " + value);
    wf_body_bottom.getObj("scwin").setReturnValue("index : " + index);
}
